<div class="page-bar"><ul class="page-breadcrumb"><li><i class="fa fa-home"></i> <a href="/<?= ADM_CONTROLLER ?>/menu/">Главная</a> <i class="fa fa-circle"></i></li><li><a href="<?= $parent_url ?>"><?= $parent_title ?></a> <i class="fa fa-circle"></i></li><li><span><?= htmlspecialchars($title, ENT_QUOTES, 'UTF-8') ?></span></li></ul></div>
<h1 class="page-title"><?= htmlspecialchars($title, ENT_QUOTES, 'UTF-8') ?></h1>
<?php if (isset($_SESSION['success'])) : ?><div class="alert alert-success"><?= $_SESSION['success']; unset($_SESSION['success']); ?></div><?php endif; ?>
<?php if (isset($_SESSION['error'])) : ?><div class="alert alert-danger"><?php foreach ($_SESSION['error'] as $error) echo htmlspecialchars($error, ENT_QUOTES, 'UTF-8') . '<br>'; unset($_SESSION['error']); ?></div><?php endif; ?>
<div class="row"><div class="portlet light"><div class="portlet-body"><form method="post" enctype="multipart/form-data"><div class="panel-body">
<?php foreach (array('RU', 'RO') as $lang) : ?><div class="form-group"><label>Название <?= $lang ?> *</label><input class="form-control" name="title<?= $lang ?>" required value="<?= htmlspecialchars($item->{'title' . $lang}, ENT_QUOTES, 'UTF-8') ?>"></div><div class="form-group"><label>Короткое описание <?= $lang ?></label><textarea class="form-control" name="desc<?= $lang ?>" rows="2"><?= htmlspecialchars($item->{'desc' . $lang}, ENT_QUOTES, 'UTF-8') ?></textarea></div><div class="form-group"><label>Текст подборки <?= $lang ?></label><textarea class="form-control ckeditor" name="text<?= $lang ?>" rows="4"><?= $item->{'text' . $lang} ?></textarea></div><div class="form-group"><label>Обложка <?= $lang ?></label><input class="form-control" type="file" name="img<?= $lang ?>"><?php if (!empty($item->{'img' . $lang})) : ?><img src="<?= newthumbs($item->{'img' . $lang}, 'beauty_selections', 220, 140, '220x140x1', 1) ?>" style="max-width:220px;margin-top:8px" alt=""><?php endif; ?></div><?php endforeach; ?>
<div class="form-group"><label>Товары</label><div class="beauty-selection-picker" data-lookup="<?= $parent_url ?>product_lookup"><input class="form-control" type="search" data-product-search placeholder="Найти товар по названию, артикулу или ID"><div data-product-results style="margin-top:8px"></div><div data-product-selected style="margin-top:8px"><?php foreach ($products as $product) : ?><span data-existing-product="<?= (int) $product->id ?>" style="display:inline-block;padding:6px 10px;margin:0 6px 6px 0;background:#eef2f5;border-radius:3px"><?= htmlspecialchars($product->{'title' . get_language_for_admin(true)}, ENT_QUOTES, 'UTF-8') ?> <small>#<?= (int) $product->id ?></small> <button type="button" data-remove style="border:0;background:none;color:#c00">×</button><input type="hidden" name="product_ids[]" value="<?= (int) $product->id ?>"></span><?php endforeach; ?></div></div></div>
<div class="form-group"><label>Порядок</label><input class="form-control" type="number" name="sorder" value="<?= (int) $item->sorder ?>" style="max-width:120px"></div><label class="mt-checkbox mt-checkbox-outline"><input type="checkbox" name="isShown" value="1" <?= !empty($item->isShown) ? 'checked' : '' ?>> Показывать на сайте<span></span></label><p><button class="btn green" type="submit"><i class="fa fa-check"></i> Сохранить</button></p>
</div></form></div></div></div>
<script>(function(){var root=document.querySelector('.beauty-selection-picker');if(!root)return;var input=root.querySelector('[data-product-search]'),results=root.querySelector('[data-product-results]'),selected=root.querySelector('[data-product-selected]'),ids={};selected.querySelectorAll('[data-existing-product]').forEach(function(row){ids[row.dataset.existingProduct]=1;row.querySelector('[data-remove]').onclick=function(){delete ids[row.dataset.existingProduct];row.remove()}});function add(p){if(ids[p.id])return;ids[p.id]=1;var row=document.createElement('span');row.style.cssText='display:inline-block;padding:6px 10px;margin:0 6px 6px 0;background:#eef2f5;border-radius:3px';row.innerHTML=(p.titleRU||p.titleRO||'Товар')+' <small>#'+p.id+'</small> <button type="button" data-remove style="border:0;background:none;color:#c00">×</button><input type="hidden" name="product_ids[]" value="'+p.id+'">';row.querySelector('[data-remove]').onclick=function(){delete ids[p.id];row.remove()};selected.appendChild(row)}function search(){var q=input.value.trim();if(q.length<2){results.innerHTML='';return}fetch(root.dataset.lookup+'?q='+encodeURIComponent(q)).then(function(r){return r.json()}).then(function(list){results.innerHTML=list.map(function(p){return '<button type="button" class="btn btn-xs default" data-id="'+p.id+'" style="margin:0 5px 5px 0">'+(p.titleRU||p.titleRO)+' (#'+p.id+')</button>'}).join('');results.querySelectorAll('[data-id]').forEach(function(b){b.onclick=function(){var p=list.find(function(x){return String(x.id)===b.dataset.id});add(p);input.value='';results.innerHTML=''}})});}input.addEventListener('input',search)})();</script>
